def _is_tier_a_source(source_name: str, url: str, title: str = "") -> bool:
    blob = _normalize_ws(f"{source_name} {url} {title}")
    if not blob:
        return False
    return bool(_TIER_A_SOURCE_RE.search(blob) or _TIER_A_URL_RE.search(_normalize_ws(url)))


