    # --- iter73: content_mix.meta.json + all content gates ---
    _cm71_bt_actionable = sum(1 for s in _selected if _ct71_is_bigtech_actionable(s))
    _cm72_bt_om_actionable = sum(1 for s in _selected if _ct72b_is_bigtech_official_media_actionable(s))
    _cm71_rt_total = sum(1 for s in _selected if _ct71_is_research_tutorial(s))
    _cm73_lp_count = sum(1 for s in _selected if _is_leadership_politics_ai(s))
    _cm73_china_count = sum(1 for s in _selected if _is_china_ai_gov(s))
    _cm74_google_research_total = sum(1 for s in _selected if _f6_is_google_research_blog(s))  # iter74
    _cm75_devrel_total = sum(1 for s in _selected if _is_developer_release(s))  # iter75
    _cm75_indie_total = sum(1 for s in _selected if _is_indie_dev_tone(s))  # iter75
    _cm77_forum_total = sum(1 for s in _selected if _is_forum_discussion(s))  # iter77
    _cm77_tutorial_total = sum(1 for s in _selected if _is_tutorial_explainer(s))  # iter77
    _cm77_official_media_count = sum(1 for s in _selected if _ct72b_source_class(s) in ("official", "media"))  # iter77
    _cm78_tc_total = sum(1 for s in _selected if _is_techcrunch(s))  # iter78
    _cm78_hfbe_total = sum(1 for s in _selected if _is_hf_blog_explainer(s))  # iter78
    _cm78_target_players = sorted(set(_f6_vendor_key(s) for s in _selected if _is_target_player(s)))  # iter78
    _cm78_target_player_distinct = len(_cm78_target_players)  # iter78
    _cm78_us_policy_count = sum(1 for s in _selected if _is_us_policy(s))  # iter78
    _cm78_china_policy_count = sum(1 for s in _selected if _is_china_policy(s))  # iter78
    _cm79_tc_gr_combined = _cm78_tc_total + _cm74_google_research_total  # iter79: combined TC+GR
    _cm79_role_axes = sorted(set(_role_axis(s) for s in _selected))  # iter79: role axes
    _cm79_role_axes_distinct = len(_cm79_role_axes)  # iter79
    _cm82_tc_rumor_total = sum(1 for s in _selected if _is_techcrunch_rumor_speculation(s))  # iter82
    _cm82_nsgr_total = sum(1 for s in _selected if _is_non_strategic_google_research(s))  # iter82
    _cm82_exec_signal_total = sum(1 for s in _selected if _is_executive_signal(s))  # iter82
    _cm84_rumor_spec_total = sum(1 for s in _selected if _is_rumor_speculation_any(s))  # iter84
    _cm84_tutorial_sem_total = sum(1 for s in _selected if _is_tutorial_semantic(s))  # iter84
    _cm89_aws_devdoc_total = sum(1 for s in _selected if _is_aws_devdoc(s))  # iter89
